SELECT mu.nm_mun, ROUND((ST_Area(ST_Transform(ST_Intersection(mu.geometry, ST_Buffer(ST_Centroid(mu.geometry), 0.1)), 5880)) / 1e6)::numeric, 2) AS area_inter_km2
FROM municipio mu
WHERE mu.nm_mun = 'Maceió';

SELECT mu.nm_mun, ROUND((ST_Area(ST_Transform(ST_Intersection(mu.geometry, ST_Buffer(ST_Centroid(mu.geometry), 0.1)), 5880)) / 1e6)::numeric, 2) AS area_inter_km2
FROM municipio mu
WHERE mu.nm_mun = 'Rio de Janeiro';

SELECT mu.nm_mun, ROUND((ST_Area(ST_Transform(ST_Intersection(mu.geometry, ST_Buffer(ST_Centroid(mu.geometry), 0.1)), 5880)) / 1e6)::numeric, 2) AS area_inter_km2
FROM municipio mu
WHERE mu.nm_mun = 'João Pessoa';

SELECT e.nm_entidade
FROM escola e
WHERE ST_Intersects(ST_Buffer(ST_SetSRID(ST_MakePoint(-43.1914, -22.9212), 4674)::geography, 20000), e.geometry::geography);

SELECT e.nm_entidade
FROM escola e
WHERE ST_Intersects(ST_Buffer(ST_SetSRID(ST_MakePoint(-54.6406, -20.4667), 4674)::geography, 2000), e.geometry::geography);

SELECT e.nm_entidade
FROM escola e
WHERE ST_Intersects(ST_Buffer(ST_SetSRID(ST_MakePoint(-35.2172, -5.789), 4674)::geography, 8000), e.geometry::geography);
